package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The rates for each grade on a sheet, each applying from its from-date. */
@Service
public class RateService {

    private final RateRepository rates;
    private final SheetService sheets;
    private final Rollup rollup;
    private final Audit audit;
    private final Dues dues;
    private final PersonRepository people;
    private final ClaimRepository claims;

    public RateService(RateRepository rates, SheetService sheets, Rollup rollup, Audit audit, Dues dues,
            PersonRepository people, ClaimRepository claims) {
        this.rates = rates;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
        this.dues = dues;
        this.people = people;
        this.claims = claims;
    }

    /** What a candidate rate would change: how many claims would show a different due, and the sum of
     *  the differences (new due minus current due; a due of n/a taken as 0.00). */
    public record Preview(int count, BigDecimal diff) {
    }

    /** Preview a candidate rate applying to a grade on every date: the open and pending claims of
     *  people on that grade (the grade in force on the claim's date) whose due would differ. A claim
     *  bound by a statement keeps its bound figure; a settled claim is not counted. Saves nothing. */
    @Transactional(readOnly = true)
    public Preview preview(String sheetId, String grade, BigDecimal pct) {
        Dues.Basis now = dues.now(sheetId);
        List<Rate> candidate = List.of(new Rate(sheetId, grade, pct, null));
        Dues.Basis with = new Dues.Basis() {
            @Override
            public LocalDate today() {
                return now.today();
            }

            @Override
            public BigDecimal floor(LocalDate day) {
                return now.floor(day);
            }

            @Override
            public BigDecimal latePct(LocalDate day) {
                return now.latePct(day);
            }

            @Override
            public BigDecimal cap() {
                return now.cap();
            }

            @Override
            public LocalDate policyDateInForce() {
                return now.policyDateInForce();
            }

            @Override
            public List<Rate> rates(String g) {
                return g.equals(grade) ? candidate : now.rates(g);
            }

            @Override
            public int grace(String g, LocalDate day) {
                return now.grace(g, day);
            }

            @Override
            public Optional<Rate> inherited(String g, LocalDate day) {
                return g.equals(grade) ? Optional.empty() : now.inherited(g, day);
            }
        };
        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        BigDecimal zero = BigDecimal.ZERO.setScale(2);
        int count = 0;
        BigDecimal diff = zero;
        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING)
                    || !grade.equals(person.gradeOn(claim.getDate()))) {
                continue;
            }
            BigDecimal was = dues.figure(now, person, claim);
            BigDecimal would = dues.figure(with, person, claim);
            BigDecimal wasValue = was == null ? zero : was;
            BigDecimal wouldValue = would == null ? zero : would;
            if ((was == null) != (would == null) || wasValue.compareTo(wouldValue) != 0) {
                count++;
                diff = diff.add(wouldValue.subtract(wasValue));
            }
        }
        return new Preview(count, diff.setScale(2));
    }

    /** The rates set on the sheet, by grade and then from-date. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrdered(sheetId);
    }

    /** The rates set on each of the sheet's ancestors, nearest first (its parent's, then the
     *  parent's parent's, up to three levels up), each by grade and then from-date. */
    @Transactional(readOnly = true)
    public List<List<Rate>> inherited(String sheetId) {
        return sheets.ancestors(sheetId).stream().map(rates::findBySheetIdOrdered).toList();
    }

    /** Set the rate for a grade from a date (null: from the beginning of time) through a date
     *  (null: no end), replacing the one the grade had for that from-date. */
    @Transactional
    public synchronized Rate set(String sheetId, String user, String grade, BigDecimal pct, LocalDate from,
            LocalDate to) {
        sheets.load(sheetId, user);
        return rollup.tracking(sheetId, user, () -> {
            Rate rate = (from == null
                    ? rates.findBySheetIdAndGradeAndFromDateIsNull(sheetId, grade)
                    : rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from))
                    .orElseGet(() -> new Rate(sheetId, grade, pct, from));
            rate.setPct(pct);
            rate.setToDate(to);
            Rate saved = rates.saveAndFlush(rate);
            audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + grade
                    + " rate=" + saved.getPct().setScale(2).toPlainString()
                    + (from != null ? " from=" + from : "")
                    + (to != null ? " to=" + to : ""));
            return saved;
        });
    }
}
package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.AssertTrue;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.sheet.AsOfGuard;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
@Validated
public class RateController {

    /** What the screen shows of a rate; the percent as text with two decimals, the from-date
     *  (null when it applies from the beginning of time) and the to-date (null when it has no end);
     *  and the level it is set on: 0 for the sheet itself, 1 for its parent, 2 for the parent's
     *  parent, and so on. */
    public record RateView(String grade, String pct, LocalDate from, LocalDate to, int level) {
        static RateView of(Rate rate) {
            return of(rate, 0);
        }

        static RateView of(Rate rate, int level) {
            return new RateView(rate.getGrade(), rate.getPct().setScale(2).toPlainString(), rate.getFromDate(),
                    rate.getToDate(), level);
        }
    }

    /** The rate form: a percent of 0.00 or more with up to two decimals, and an optional from-date
     *  (left out: from the beginning of time) and an optional to-date not before it (left out: no
     *  end). */
    public record RateForm(@NotNull @Pattern(regexp = "\\s*\\d{1,5}(\\.\\d{1,2})?\\s*") String pct,
            LocalDate from, LocalDate to) {

        @AssertTrue
        public boolean isToNotBeforeFrom() {
            return from == null || to == null || !to.isBefore(from);
        }

        BigDecimal pctValue() {
            return new BigDecimal(pct.trim()).setScale(2);
        }
    }

    private final RateService service;
    private final History history;

    public RateController(RateService service, History history) {
        this.service = service;
        this.history = history;
    }

    /** The rates on the sheet; as of a day when one is given, as they stood at the end of it (see
     *  {@link History}); then the rates of its ancestors, nearest first, likewise as of that day when
     *  one is given (a grade with no rate in force on a date on the sheet takes theirs). */
    @GetMapping
    public List<RateView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
            LocalDate asOf) {
        History.SheetAsOf then = asOf != null ? history.asOf(sheetId.trim(), asOf) : null;
        List<Rate> rates = then != null ? then.rates() : service.list(sheetId.trim());
        List<RateView> views = new ArrayList<>(rates.stream().map(RateView::of).toList());
        List<List<Rate>> inherited = then != null ? then.inherited() : service.inherited(sheetId.trim());
        for (int i = 0; i < inherited.size(); i++) {
            int level = i + 1;
            inherited.get(i).forEach(rate -> views.add(RateView.of(rate, level)));
        }
        return views;
    }

    /** What the screen shows of a rate preview: the count and the sum of the differences as text with
     *  two decimals. */
    public record PreviewView(int count, String diff) {
    }

    /** Preview a candidate rate for a grade (see {@link RateService#preview}); nothing is saved. */
    @GetMapping("/{grade}/preview")
    public PreviewView preview(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestParam @NotNull @Pattern(regexp = "\\s*\\d{1,5}(\\.\\d{1,2})?\\s*") String pct) {
        RateService.Preview preview = service.preview(sheetId.trim(), grade, new BigDecimal(pct.trim()).setScale(2));
        return new PreviewView(preview.count(), preview.diff().toPlainString());
    }

    @PutMapping("/{grade}")
    public RateView set(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody RateForm form) {
        return RateView.of(service.set(sheetId.trim(), user.trim(), grade, form.pctValue(), form.from(),
                form.to()));
    }
}
