    public Preview preview(String sheetId, String grade, BigDecimal pct) {
        Dues.Basis now = dues.now(sheetId);
        List<Rate> candidate = List.of(new Rate(sheetId, grade, pct, null));
        Dues.Basis with = new Dues.Basis() {
            @Override
            public LocalDate today() {
                return now.today();
            }

            @Override
            public BigDecimal floor(LocalDate day) {
                return now.floor(day);
            }

            @Override
            public BigDecimal latePct(LocalDate day) {
                return now.latePct(day);
            }

            @Override
            public BigDecimal cap() {
                return now.cap();
            }

            @Override
            public LocalDate policyDateInForce() {
                return now.policyDateInForce();
            }

            @Override
            public List<Rate> rates(String g) {
                return g.equals(grade) ? candidate : now.rates(g);
            }

            @Override
            public int grace(String g, LocalDate day) {
                return now.grace(g, day);
            }

            @Override
            public Optional<Rate> inherited(String g, LocalDate day) {
                return g.equals(grade) ? Optional.empty() : now.inherited(g, day);
            }
        };
        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        BigDecimal zero = BigDecimal.ZERO.setScale(2);
        int count = 0;
        BigDecimal diff = zero;
        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING)
                    || !grade.equals(person.gradeOn(claim.getDate()))) {
                continue;
            }
            BigDecimal was = dues.figure(now, person, claim);
            BigDecimal would = dues.figure(with, person, claim);
            BigDecimal wasValue = was == null ? zero : was;
            BigDecimal wouldValue = would == null ? zero : would;
            if ((was == null) != (would == null) || wasValue.compareTo(wouldValue) != 0) {
                count++;
                diff = diff.add(wouldValue.subtract(wasValue));
            }
        }
        return new Preview(count, diff.setScale(2));
    }

    /** The rates set on the sheet, by grade and then from-date. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrdered(sheetId);
    }

    /** The rates set on each of the sheet's ancestors, nearest first (its parent's, then the
     *  parent's parent's, up to three levels up), each by grade and then from-date. */
    @Transactional(readOnly = true)
    public List<List<Rate>> inherited(String sheetId) {
        return sheets.ancestors(sheetId).stream().map(rates::findBySheetIdOrdered).toList();
    }

    /** Set the rate for a grade from a date (null: from the beginning of time) through a date
     *  (null: no end), replacing the one the grade had for that from-date. */
    @Transactional
    public synchronized Rate set(String sheetId, String user, String grade, BigDecimal pct, LocalDate from,
            LocalDate to) {
        sheets.load(sheetId, user);
        return rollup.tracking(sheetId, user, () -> {
            Rate rate = (from == null
                    ? rates.findBySheetIdAndGradeAndFromDateIsNull(sheetId, grade)
                    : rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from))
                    .orElseGet(() -> new Rate(sheetId, grade, pct, from));
            rate.setPct(pct);
            rate.setToDate(to);
            Rate saved = rates.saveAndFlush(rate);
            audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + grade
                    + " rate=" + saved.getPct().setScale(2).toPlainString()
                    + (from != null ? " from=" + from : "")
                    + (to != null ? " to=" + to : ""));
            return saved;
        });
    }
}
package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.AssertTrue;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.sheet.AsOfGuard;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
@Validated
public class RateController {

    /** What the screen shows of a rate; the percent as text with two decimals, the from-date
     *  (null when it applies from the beginning of time) and the to-date (null when it has no end);
     *  and the level it is set on: 0 for the sheet itself, 1 for its parent, 2 for the parent's
     *  parent, and so on. */
    public record RateView(String grade, String pct, LocalDate from, LocalDate to, int level) {
        static RateView of(Rate rate) {
            return of(rate, 0);
        }

        static RateView of(Rate rate, int level) {
            return new RateView(rate.getGrade(), rate.getPct().setScale(2).toPlainString(), rate.getFromDate(),
                    rate.getToDate(), level);
        }
    }

    /** The rate form: a percent of 0.00 or more with up to two decimals, and an optional from-date
     *  (left out: from the beginning of time) and an optional to-date not before it (left out: no
     *  end). */
    public record RateForm(@NotNull @Pattern(regexp = "\\s*\\d{1,5}(\\.\\d{1,2})?\\s*") String pct,
            LocalDate from, LocalDate to) {

        @AssertTrue
        public boolean isToNotBeforeFrom() {
            return from == null || to == null || !to.isBefore(from);
        }

        BigDecimal pctValue() {
            return new BigDecimal(pct.trim()).setScale(2);
        }
    }

    private final RateService service;
    private final History history;

    public RateController(RateService service, History history) {
        this.service = service;
        this.history = history;
    }

    /** The rates on the sheet; as of a day when one is given, as they stood at the end of it (see
     *  {@link History}); then the rates of its ancestors, nearest first, likewise as of that day when
     *  one is given (a grade with no rate in force on a date on the sheet takes theirs). */
    @GetMapping
    public List<RateView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
            LocalDate asOf) {
        History.SheetAsOf then = asOf != null ? history.asOf(sheetId.trim(), asOf) : null;
        List<Rate> rates = then != null ? then.rates() : service.list(sheetId.trim());
        List<RateView> views = new ArrayList<>(rates.stream().map(RateView::of).toList());
        List<List<Rate>> inherited = then != null ? then.inherited() : service.inherited(sheetId.trim());
        for (int i = 0; i < inherited.size(); i++) {
            int level = i + 1;
            inherited.get(i).forEach(rate -> views.add(RateView.of(rate, level)));
        }
        return views;
    }

    /** What the screen shows of a rate preview: the count and the sum of the differences as text with
     *  two decimals. */
    public record PreviewView(int count, String diff) {
    }

    /** Preview a candidate rate for a grade (see {@link RateService#preview}); nothing is saved. */
    @GetMapping("/{grade}/preview")
    public PreviewView preview(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestParam @NotNull @Pattern(regexp = "\\s*\\d{1,5}(\\.\\d{1,2})?\\s*") String pct) {
        RateService.Preview preview = service.preview(sheetId.trim(), grade, new BigDecimal(pct.trim()).setScale(2));
        return new PreviewView(preview.count(), preview.diff().toPlainString());
    }

    @PutMapping("/{grade}")
    public RateView set(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody RateForm form) {
        return RateView.of(service.set(sheetId.trim(), user.trim(), grade, form.pctValue(), form.from(),
                form.to()));
    }
}
import { Component, computed, inject, input, output, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Grade } from '../../core/people';
import { PCT, Rate, RatePreview, Rates, pctOn } from '../../core/rates';
import { Session } from '../../core/session';

// The rates for each grade on the sheet, the one in force on the sheet's today, and the form that
// sets one.
@Component({
  selector: 'app-rate-form',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="rates-heading">
      <h2 id="rates-heading">Rates</h2>
      <form data-testid="rate-form" [formGroup]="form" (ngSubmit)="submit()">
        <label for="rate-form-grade">Grade</label>
        <select id="rate-form-grade" data-testid="rate-form-grade" formControlName="grade">
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <label for="rate-form-pct">Rate (%)</label>
        <input id="rate-form-pct" data-testid="rate-form-pct" formControlName="pct" inputmode="decimal" />
        <label for="rate-form-from">From</label>
        <input id="rate-form-from" type="date" data-testid="rate-form-from" formControlName="from" />
        <label for="rate-form-to">To</label>
        <input id="rate-form-to" type="date" data-testid="rate-form-to" formControlName="to" />
        <button type="submit" data-testid="rate-form-submit">Set rate</button>
        @if (error()) {
          <p role="alert" data-testid="rate-form-error">{{ error() }}</p>
        }
      </form>
      <form data-testid="rate-preview-form" [formGroup]="previewForm" (ngSubmit)="preview()">
        <label for="rate-preview-grade">Preview grade</label>
        <select id="rate-preview-grade" data-testid="rate-preview-grade" formControlName="grade">
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <label for="rate-preview-pct">Candidate rate (%)</label>
        <input id="rate-preview-pct" data-testid="rate-preview-pct" formControlName="pct" inputmode="decimal" />
        <button type="submit" data-testid="rate-preview">Preview</button>
        @if (previewError()) {
          <p role="alert" data-testid="rate-preview-error">{{ previewError() }}</p>
        }
        @if (previewResult(); as r) {
          <p aria-live="polite">
            Claims that would change: <span data-testid="rate-preview-count">{{ r.count }}</span>;
            difference: <span data-testid="rate-preview-diff">{{ r.diff }}</span>
          </p>
        }
      </form>
      <table data-testid="rates-current">
        <caption>In force on {{ session.today() }}</caption>
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">Rate (%)</th></tr>
        </thead>
        <tbody>
          @for (g of grades; track g) {
            <tr>
              <th scope="row">{{ g }}</th>
              <td [attr.data-testid]="'rate-current-' + g">{{ current().get(g) ?? 'n/a' }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table data-testid="rates">
        <caption>All rates</caption>
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">From</th><th scope="col">To</th><th scope="col">Rate (%)</th></tr>
        </thead>
        <tbody>
          @for (r of own(); track r.grade + '-' + (r.from ?? 'start')) {
            <tr [attr.data-testid]="'rate-row-' + r.grade + '-' + (r.from ?? 'start')">
              <th scope="row">{{ r.grade }}</th>
              <td data-testid="rate-from">{{ r.from ?? 'start' }}</td>
              <td data-testid="rate-to">{{ r.to ?? '…' }}</td>
              <td data-testid="rate-pct">{{ r.pct }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class RateForm {
  private readonly api = inject(Rates);
  protected readonly session = inject(Session);

  /** The rates set on the sheet, by grade and then from-date, then those of its ancestors. */
  readonly rates = input.required<Rate[]>();
  /** The rates set on the sheet itself. */
  protected readonly own = computed(() => this.rates().filter((r) => r.level === 0));
  /** A rate set through the form. */
  readonly saved = output<Rate>();

  protected readonly grades: Grade[] = ['A', 'B', 'C'];
  protected readonly error = signal('');
  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
  private submitting = false;
  protected readonly form = new FormGroup({
    grade: new FormControl<Grade>('A', { nonNullable: true }),
    pct: new FormControl('', { nonNullable: true }),
    from: new FormControl('', { nonNullable: true }),
    to: new FormControl('', { nonNullable: true }),
  });
  protected readonly previewForm = new FormGroup({
    grade: new FormControl<Grade>('A', { nonNullable: true }),
    pct: new FormControl('', { nonNullable: true }),
  });
  protected readonly previewError = signal('');
  /** The last preview's result; cleared while a preview runs and when the preview form changes. */
  protected readonly previewResult = signal<RatePreview | null>(null);
  /** Whether a preview is waiting for its answer: a second one meanwhile is ignored. */
  private previewing = false;
  /** Each grade's rate in force on the sheet's today; a grade with none is missing. */
  protected readonly current = computed(() => {
    const today = this.session.today();
    const by = new Map<Grade, string>();
    if (today === null) return by;
    for (const g of this.grades) {
      const pct = pctOn(this.rates(), g, today);
      if (pct !== undefined) by.set(g, pct);
    }
    return by;
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
    this.previewForm.valueChanges.subscribe(() => {
      this.previewError.set('');
      this.previewResult.set(null);
    });
  }

  protected async preview(): Promise<void> {
    if (this.previewing) return;
    this.previewError.set('');
    this.previewResult.set(null);
    const { grade, pct } = this.previewForm.getRawValue();
    if (!this.grades.includes(grade)) {
      this.previewError.set('Choose a grade of A, B or C.');
      return;
    }
    if (!PCT.test(pct.trim())) {
      this.previewError.set('Enter a rate of 0.00 or more, with up to two decimals.');
      return;
    }
    this.previewing = true;
    try {
      this.previewResult.set(await this.api.preview(grade, pct.trim()));
    } catch {
      this.previewError.set('The preview could not be made.');
    } finally {
      this.previewing = false;
    }
  }

  protected async submit(): Promise<void> {
    if (this.submitting) return;
    this.error.set('');
    const { grade, pct, from, to } = this.form.getRawValue();
    if (!this.grades.includes(grade)) {
      this.error.set('Choose a grade of A, B or C.');
      return;
    }
    if (!PCT.test(pct.trim())) {
      this.error.set('Enter a rate of 0.00 or more, with up to two decimals.');
      return;
    }
    const day = from.trim();
    if (day !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(day)) {
      this.error.set('Enter a from-date, or leave it blank for a rate that always applied.');
      return;
    }
    const end = to.trim();
    if (end !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(end)) {
      this.error.set('Enter a to-date, or leave it blank for a rate with no end.');
      return;
    }
    if (day !== '' && end !== '' && end < day) {
      this.error.set('The to-date cannot be before the from-date.');
      return;
    }
    this.submitting = true;
    try {
      this.saved.emit(await this.api.set(grade, pct.trim(), day === '' ? null : day, end === '' ? null : end));
      this.form.reset({ grade: 'A', pct: '', from: '', to: '' }, { emitEvent: false });
    } catch {
      this.error.set('The rate could not be set.');
    } finally {
      this.submitting = false;
    }
  }
}
